int get_data_block(struct inode *inode, sector_t iblock, struct buffer_head *bh, int create, int flag, pgoff_t *next_pgofs) {
    int ret;
    struct address_space *mapping = inode->i_mapping;
    struct bvec bv;
    struct page *page;

    bv.bv_page = NULL;
    bv.bv_len = bh->b_size;
    bv.bv_offset = 0;

    ret = map_blocks(mapping, iblock, &bv, create, flag);
    if (ret < 0)
        return ret;

    page = bv.bv_page;
    if (!page)
        return -EINVAL;

    bh->b_page = page;
    bh->b_blocknr = iblock;
    bh->b_size = bv.bv_len;
    bh->b_state = 0;

    if (next_pgofs)
        *next_pgofs = iblock + 1;

    return 0;
}

int get_data_block(struct inode *inode, sector_t iblock, struct buffer_head *bh, int create, int flag, pgoff_t *next_pgofs) {
    struct address_space *mapping = inode->i_mapping;
    int ret;

    ret = mapping->a_ops->bmap(mapping, iblock, bh, create, flag);
    if (ret < 0)
        return ret;

    if (next_pgofs)
        *next_pgofs = (pgoff_t)(iblock + 1) << (PAGE_SHIFT - inode->i_blkbits);

    return 0;
}
